using System;
string[] records = { "Ada, 98 ,CS", "Ada,CS", "Ada,98,CS,extra", "Ada,abc,CS", "Ada,101,CS" };
foreach (string record in records)
{
    string[] fields = record.Split(',');
    string outcome;
    if (fields.Length != 3) outcome = "reject shape";
    else if (!int.TryParse(fields[1], out int score)) outcome = "reject number";
    else if (score < 0 || score > 100) outcome = "reject range";
    else outcome = $"accept {fields[0].Trim()}: {score}";
    Console.WriteLine($"{record} -> {outcome}");
}

using System;
using System.Collections.Generic;
using System.Linq;
int[] values = { 3, -1, 2, 0 };
var loopResult = new List<int>();
foreach (int value in values)
    if (value > 0) loopResult.Add(value * 10);
loopResult.Sort();
var query = values.Where(x => x > 0).Select(x => x * 10).OrderBy(x => x);
int[] snapshot = query.ToArray();
Console.WriteLine("Loop: " + string.Join(",", loopResult));
Console.WriteLine("Snapshot: " + string.Join(",", snapshot));
values[0] = 4;
Console.WriteLine("Query after edit: " + string.Join(",", query));
Console.WriteLine("Snapshot after edit: " + string.Join(",", snapshot));

